INSERT INTO saju_narrative_rule (category, hanja, data) VALUES
('day', '甲子', '{"code": "갑자", "keywords": ["개척", "주도성", "성장"], "strengths": ["결단력", "책임감"], "weaknesses": ["완고함", "혼자 짊어짐"], "career": ["새로운 기획", "팀의 방향 설정"], "relationship": ["꾸준한 신뢰", "상대의 속도 존중"], "intro": "방향이 보이면 먼저 길을 내고 싶어 하는 쪽에 가까워요. 누군가 정해 준 답을 따르기보다 직접 기준을 세울 때 마음이 편할 수 있어요.", "strength_text": "시작이 막막한 순간에 해야 할 일을 정리하고 사람들을 이끄는 힘이 있어요.", "caution_text": "내가 책임져야 한다는 마음이 커지면 도움을 청하는 시기를 놓칠 수 있어요. 의견을 듣는 시간도 계획에 넣어 보세요.", "career_text": "새로운 일을 기획하거나 팀의 방향을 잡는 자리에서 역량을 드러내기 좋아요.", "relationship_text": "말보다 꾸준한 행동으로 신뢰를 쌓는 편이에요. 상대에게도 스스로 선택할 여유를 주면 관계가 한결 편안해져요.", "branch_text": "겉으로 빠르게 드러내기보다 속으로 가능성을 비교하는 면도 함께 있어요. 결정을 내릴 시간을 확보하면 내 장점을 더 편하게 쓸 수 있어요.", "subtitle": "생각을 깊이 모으는 힘"}'),
('day', '乙丑', '{"code": "을축", "keywords": ["적응력", "섬세함", "유연함"], "strengths": ["조율", "끈기"], "weaknesses": ["눈치 보기", "결정 미루기"], "career": ["협업과 조정", "세밀한 기획"], "relationship": ["세심한 배려", "분명한 의사 표현"], "intro": "주변의 작은 변화를 잘 읽고 상황에 맞게 방법을 바꾸는 쪽에 가까워요. 강하게 밀어붙이기보다 연결점을 찾으며 길을 만드는 모습이 보여요.", "strength_text": "서로 다른 의견 사이에서 접점을 찾고, 작은 일을 오래 다듬는 힘이 있어요.", "caution_text": "상대의 마음을 먼저 살피다 보면 정작 내 바람을 뒤로 미룰 수 있어요. 양보할 수 없는 기준을 하나 정해 두세요.", "career_text": "협업을 조율하거나 사용자의 마음을 세밀하게 읽는 일에서 장점이 살아나요.", "relationship_text": "작은 배려를 잘 기억하고 돌려주는 편이에요. 서운함이 쌓이기 전에 짧고 구체적으로 이야기하는 연습이 도움이 돼요.", "branch_text": "결과가 바로 보이지 않아도 차근차근 쌓아 가려는 면이 함께 있어요. 중간 성과를 확인하는 작은 기준이 꾸준함을 지켜 줘요.", "subtitle": "꾸준히 쌓아 가는 힘"}'),
('day', '丙寅', '{"code": "병인", "keywords": ["활동적", "추진력", "표현력", "승부욕"], "strengths": ["실행력", "리더십"], "weaknesses": ["성급함", "과열"], "career": ["주도적인 업무", "전문성 표현"], "relationship": ["직접적인 감정 표현", "강한 자기주장 주의"], "intro": "생각만 오래 붙잡기보다 직접 움직이며 답을 찾는 쪽에 가까워요. 마음에 불이 붙은 일에는 존재감이 선명해지고, 주변에도 의욕을 전하는 모습이 보여요.", "strength_text": "망설이는 상황에서 첫걸음을 떼고 사람들을 움직이게 하는 힘이 있어요. 잘하는 것을 드러낼 기회가 생기면 자신감도 함께 살아나요.", "caution_text": "속도가 붙을수록 결론을 서두르거나 한 번에 너무 많은 일을 맡기 쉬워요. 중요한 결정 앞에서는 한 박자 쉬며 끝까지 가져갈 여력을 확인해 보세요.", "career_text": "스스로 방향을 잡는 업무나 기획·발표처럼 전문성을 눈에 보이게 표현하는 일에서 강점을 살리기 좋아요.", "relationship_text": "좋아하는 마음을 비교적 직접적으로 전하는 편이에요. 내 확신이 상대에게는 압박으로 느껴질 수 있으니, 말을 건넨 뒤 상대의 속도도 기다려 주세요.", "branch_text": "익숙한 곳을 벗어나 새로운 기회를 시험하고 싶은 마음도 함께 보여요. 시작한 일을 다듬는 시간까지 남겨 두면 좋아요.", "subtitle": "새로운 기회를 향한 의욕"}'),
('day', '丁卯', '{"code": "정묘", "keywords": ["따뜻함", "집중력", "감수성"], "strengths": ["세심한 관찰", "몰입"], "weaknesses": ["걱정 쌓기", "감정 소모"], "career": ["전문 기술", "돌봄과 교육"], "relationship": ["깊은 교감", "감정의 경계"], "intro": "크게 드러내기보다 가까운 사람과 중요한 일에 오래 마음을 쓰는 쪽에 가까워요. 관심이 생긴 대상은 작은 차이까지 살피며 깊이를 더하는 모습이에요.", "strength_text": "작은 신호를 놓치지 않고 필요한 순간에 정교하게 힘을 쓰는 장점이 있어요.", "caution_text": "마음에 담아 둔 일이 많아지면 혼자 지칠 수 있어요. 신경 쓰이는 일을 적어 보고 내 몫과 상대의 몫을 나눠 보세요.", "career_text": "한 분야를 깊이 익히는 전문 업무나 누군가의 성장을 돕는 일에서 보람을 찾기 좋아요.", "relationship_text": "넓고 가벼운 만남보다 깊이 통하는 관계를 소중히 여겨요. 마음을 읽어 주기만 기다리기보다 필요한 도움을 말로 알려 주세요.", "branch_text": "사람 사이의 분위기를 부드럽게 맞추려는 면도 함께 있어요. 편안한 관계 안에서 내 의견도 분명히 드러내 보세요.", "subtitle": "관계의 결을 읽는 감각"}'),
('day', '戊辰', '{"code": "무진", "keywords": ["안정감", "책임감", "신중함"], "strengths": ["지속력", "신뢰"], "weaknesses": ["변화 부담", "고집"], "career": ["장기 프로젝트", "운영 관리"], "relationship": ["든든한 지지", "유연한 대화"], "intro": "한번 맡은 일은 쉽게 흔들리지 않고 버텨 내는 쪽에 가까워요. 빠른 성과보다 오래 지킬 수 있는 기반을 중요하게 느낄 수 있어요.", "strength_text": "복잡한 상황에서도 중심을 잡고 일을 꾸준히 이어 가는 힘이 있어요.", "caution_text": "익숙한 방식을 지키려는 마음이 새로운 가능성을 좁힐 수 있어요. 큰 변화보다 작은 실험부터 시작해 보세요.", "career_text": "여러 사람의 일을 안정적으로 연결하는 운영이나 긴 호흡의 프로젝트에서 역량이 드러나요.", "relationship_text": "곁에 있어 주는 것 자체로 마음을 표현하는 편이에요. 상대는 말로 확인받고 싶을 수 있으니 고마움을 조금 더 자주 전해 보세요.", "branch_text": "지금 모습에 머물기보다 더 큰 가능성을 마음에 품는 면이 있어요. 여러 계획 중 이번에 실현할 한 가지를 골라 보세요.", "subtitle": "변화를 담아내는 가능성"}'),
('day', '己巳', '{"code": "기사", "keywords": ["포용력", "현실감각", "꼼꼼함"], "strengths": ["지원", "관리 능력"], "weaknesses": ["과한 배려", "걱정"], "career": ["자원 관리", "실무 지원"], "relationship": ["생활 속 배려", "요구 전달"], "intro": "눈앞의 필요를 살피고 현실적으로 도움이 되는 방법을 찾는 쪽에 가까워요. 작은 것을 챙기며 전체를 안정시키는 모습이 보여요.", "strength_text": "흩어진 일과 자원을 정리하고 다른 사람이 제 몫을 할 수 있게 돕는 힘이 있어요.", "caution_text": "모두를 챙기려다 내 계획이 계속 밀릴 수 있어요. 도움을 주기 전에 가능한 범위를 먼저 정해 보세요.", "career_text": "세부 운영을 다듬거나 사람과 자원을 효율적으로 연결하는 일에서 장점을 살리기 좋아요.", "relationship_text": "거창한 말보다 생활 속 배려를 중요하게 여겨요. 나도 돌봄을 받을 수 있도록 원하는 것을 숨기지 않아도 괜찮아요.", "branch_text": "겉으로 보이는 것보다 안쪽의 이유를 알고 싶어 하는 면도 있어요. 충분히 살펴본 뒤에는 작은 실행으로 생각을 확인해 보세요.", "subtitle": "깊이 살펴보는 집중력"}'),
('day', '庚午', '{"code": "경오", "keywords": ["결단력", "원칙", "도전"], "strengths": ["문제 해결", "실행"], "weaknesses": ["직설적 표현", "경직됨"], "career": ["문제 해결 업무", "체계 개선"], "relationship": ["명확한 약속", "부드러운 표현"], "intro": "문제가 보이면 핵심을 짚고 빠르게 정리하고 싶어 하는 쪽에 가까워요. 애매한 상태보다 기준이 분명한 상황에서 힘이 나기 쉬워요.", "strength_text": "어려운 결정을 피하지 않고 불필요한 과정을 줄이는 힘이 있어요.", "caution_text": "옳은 이야기도 너무 단단하게 전하면 상대가 마음을 닫을 수 있어요. 해결책을 말하기 전에 상대가 겪은 어려움을 먼저 들어 주세요.", "career_text": "엉킨 문제를 풀거나 비효율적인 체계를 개선하는 업무에서 역량이 살아나요.", "relationship_text": "말과 행동이 일치하는 관계를 편안하게 느껴요. 약속만큼 감정도 대화의 주제로 두면 관계가 더 부드러워져요.", "branch_text": "마음이 움직이는 순간 표현과 행동도 함께 커지기 쉬워요. 몰입할 일과 쉬어 갈 시간을 나눠 두면 열정을 오래 이어 갈 수 있어요.", "subtitle": "마음을 행동으로 옮기는 열기"}'),
('day', '辛未', '{"code": "신미", "keywords": ["정교함", "분석력", "미감"], "strengths": ["완성도", "집중력"], "weaknesses": ["완벽주의", "예민함"], "career": ["분석과 검수", "정밀한 표현"], "relationship": ["섬세한 취향", "기대 조율"], "intro": "작은 차이에서도 의미를 찾아내고 내 기준에 맞게 다듬는 쪽에 가까워요. 대충 넘어가기보다 완성도를 높일 때 만족감이 커질 수 있어요.", "strength_text": "세부의 오류를 찾고 결과물의 품질을 한 단계 올리는 힘이 있어요.", "caution_text": "완벽한 상태를 기다리면 시작이나 마무리가 늦어질 수 있어요. 이번 단계에 충분한 기준을 먼저 정해 보세요.", "career_text": "분석·검수나 정교한 감각을 표현하는 업무에서 집중력이 빛나기 좋아요.", "relationship_text": "세심하게 알아주는 말에 마음이 움직이는 편이에요. 상대도 같은 기준을 알 수 있도록 기대를 구체적으로 나눠 주세요.", "branch_text": "내 일만큼 가까운 사람의 편안함을 살피는 면도 함께 있어요. 배려와 내 필요 사이의 균형을 잡아 보세요.", "subtitle": "주변을 살피는 다정함"}'),
('day', '壬申', '{"code": "임신", "keywords": ["유연함", "탐구심", "넓은 시야"], "strengths": ["상황 판단", "연결 능력"], "weaknesses": ["방향 분산", "마무리 지연"], "career": ["정보 연결", "전략 수립"], "relationship": ["열린 대화", "일관된 표현"], "intro": "한 가지 답에 묶이기보다 여러 가능성을 살피는 쪽에 가까워요. 사람과 정보 사이의 흐름을 읽으며 새로운 길을 찾아가는 모습이에요.", "strength_text": "서로 떨어져 있던 생각을 연결하고 큰 흐름 속에서 선택지를 찾는 힘이 있어요.", "caution_text": "가능성이 많을수록 방향이 자주 바뀔 수 있어요. 지금 끝낼 일 하나를 고르면 넓은 시야가 실행으로 이어져요.", "career_text": "정보를 엮어 전략을 만들거나 다양한 사람을 연결하는 일에서 장점이 살아나요.", "relationship_text": "생각을 자유롭게 나눌 수 있는 관계를 편안하게 느껴요. 중요한 마음은 상황이 바뀌어도 일관되게 보여 주는 것이 좋아요.", "branch_text": "변화하는 상황에 맞춰 방법을 바꾸는 재치도 함께 보여요. 새로운 방법을 찾되 마무리 기준은 일정하게 두면 좋아요.", "subtitle": "상황에 맞춰 움직이는 재치"}'),
('day', '癸酉', '{"code": "계유", "keywords": ["직관", "관찰력", "신중함"], "strengths": ["공감", "깊은 사고"], "weaknesses": ["과도한 생각", "표현 주저"], "career": ["연구와 기록", "세밀한 상담"], "relationship": ["조용한 교감", "솔직한 요청"], "intro": "먼저 충분히 관찰하고 내 안에서 생각을 정리하는 쪽에 가까워요. 겉으로 드러난 말보다 미묘한 분위기를 세심하게 읽는 모습이에요.", "strength_text": "다른 사람이 지나친 단서를 모아 새로운 이해로 연결하는 힘이 있어요.", "caution_text": "생각이 많아질수록 아직 일어나지 않은 일까지 걱정하기 쉬워요. 확인된 사실과 추측을 나눠 적어 보세요.", "career_text": "깊이 탐구하고 기록하거나 상대의 이야기를 세심하게 듣는 일에서 역량을 살리기 좋아요.", "relationship_text": "조용히 통하는 관계를 소중히 여기지만 내 마음이 저절로 전달되지는 않아요. 작은 요청부터 솔직하게 표현해 보세요.", "branch_text": "무엇을 하든 마지막 완성도를 확인하려는 면도 있어요. 잘된 부분부터 인정하면 스스로에게 지나치게 엄격해지는 것을 줄일 수 있어요.", "subtitle": "결과를 다듬는 감각"}'),
('day', '甲戌', '{"code": "갑술", "keywords": ["개척", "주도성", "성장"], "strengths": ["결단력", "책임감"], "weaknesses": ["완고함", "혼자 짊어짐"], "career": ["새로운 기획", "팀의 방향 설정"], "relationship": ["꾸준한 신뢰", "상대의 속도 존중"], "intro": "방향이 보이면 먼저 길을 내고 싶어 하는 쪽에 가까워요. 누군가 정해 준 답을 따르기보다 직접 기준을 세울 때 마음이 편할 수 있어요.", "strength_text": "시작이 막막한 순간에 해야 할 일을 정리하고 사람들을 이끄는 힘이 있어요.", "caution_text": "내가 책임져야 한다는 마음이 커지면 도움을 청하는 시기를 놓칠 수 있어요. 의견을 듣는 시간도 계획에 넣어 보세요.", "career_text": "새로운 일을 기획하거나 팀의 방향을 잡는 자리에서 역량을 드러내기 좋아요.", "relationship_text": "말보다 꾸준한 행동으로 신뢰를 쌓는 편이에요. 상대에게도 스스로 선택할 여유를 주면 관계가 한결 편안해져요.", "branch_text": "마음속 약속과 기준을 쉽게 버리지 않는 면도 함께 있어요. 원칙을 지키면서도 방법에는 여지를 남겨 보세요.", "subtitle": "기준을 지키는 성실함"}'),
('day', '乙亥', '{"code": "을해", "keywords": ["적응력", "섬세함", "유연함"], "strengths": ["조율", "끈기"], "weaknesses": ["눈치 보기", "결정 미루기"], "career": ["협업과 조정", "세밀한 기획"], "relationship": ["세심한 배려", "분명한 의사 표현"], "intro": "주변의 작은 변화를 잘 읽고 상황에 맞게 방법을 바꾸는 쪽에 가까워요. 강하게 밀어붙이기보다 연결점을 찾으며 길을 만드는 모습이 보여요.", "strength_text": "서로 다른 의견 사이에서 접점을 찾고, 작은 일을 오래 다듬는 힘이 있어요.", "caution_text": "상대의 마음을 먼저 살피다 보면 정작 내 바람을 뒤로 미룰 수 있어요. 양보할 수 없는 기준을 하나 정해 두세요.", "career_text": "협업을 조율하거나 사용자의 마음을 세밀하게 읽는 일에서 장점이 살아나요.", "relationship_text": "작은 배려를 잘 기억하고 돌려주는 편이에요. 서운함이 쌓이기 전에 짧고 구체적으로 이야기하는 연습이 도움이 돼요.", "branch_text": "당장 드러난 결과보다 사람과 상황을 넓게 이해하려는 면도 있어요. 충분히 생각한 뒤에는 내 선택을 구체적인 약속으로 만들어 보세요.", "subtitle": "넓게 이해하는 여유"}'),
('day', '丙子', '{"code": "병자", "keywords": ["활동적", "추진력", "표현력", "승부욕"], "strengths": ["실행력", "리더십"], "weaknesses": ["성급함", "과열"], "career": ["주도적인 업무", "전문성 표현"], "relationship": ["직접적인 감정 표현", "강한 자기주장 주의"], "intro": "생각만 오래 붙잡기보다 직접 움직이며 답을 찾는 쪽에 가까워요. 마음에 불이 붙은 일에는 존재감이 선명해지고, 주변에도 의욕을 전하는 모습이 보여요.", "strength_text": "망설이는 상황에서 첫걸음을 떼고 사람들을 움직이게 하는 힘이 있어요. 잘하는 것을 드러낼 기회가 생기면 자신감도 함께 살아나요.", "caution_text": "속도가 붙을수록 결론을 서두르거나 한 번에 너무 많은 일을 맡기 쉬워요. 중요한 결정 앞에서는 한 박자 쉬며 끝까지 가져갈 여력을 확인해 보세요.", "career_text": "스스로 방향을 잡는 업무나 기획·발표처럼 전문성을 눈에 보이게 표현하는 일에서 강점을 살리기 좋아요.", "relationship_text": "좋아하는 마음을 비교적 직접적으로 전하는 편이에요. 내 확신이 상대에게는 압박으로 느껴질 수 있으니, 말을 건넨 뒤 상대의 속도도 기다려 주세요.", "branch_text": "겉으로 빠르게 드러내기보다 속으로 가능성을 비교하는 면도 함께 있어요. 결정을 내릴 시간을 확보하면 내 장점을 더 편하게 쓸 수 있어요.", "subtitle": "생각을 깊이 모으는 힘"}'),
('day', '丁丑', '{"code": "정축", "keywords": ["따뜻함", "집중력", "감수성"], "strengths": ["세심한 관찰", "몰입"], "weaknesses": ["걱정 쌓기", "감정 소모"], "career": ["전문 기술", "돌봄과 교육"], "relationship": ["깊은 교감", "감정의 경계"], "intro": "크게 드러내기보다 가까운 사람과 중요한 일에 오래 마음을 쓰는 쪽에 가까워요. 관심이 생긴 대상은 작은 차이까지 살피며 깊이를 더하는 모습이에요.", "strength_text": "작은 신호를 놓치지 않고 필요한 순간에 정교하게 힘을 쓰는 장점이 있어요.", "caution_text": "마음에 담아 둔 일이 많아지면 혼자 지칠 수 있어요. 신경 쓰이는 일을 적어 보고 내 몫과 상대의 몫을 나눠 보세요.", "career_text": "한 분야를 깊이 익히는 전문 업무나 누군가의 성장을 돕는 일에서 보람을 찾기 좋아요.", "relationship_text": "넓고 가벼운 만남보다 깊이 통하는 관계를 소중히 여겨요. 마음을 읽어 주기만 기다리기보다 필요한 도움을 말로 알려 주세요.", "branch_text": "결과가 바로 보이지 않아도 차근차근 쌓아 가려는 면이 함께 있어요. 중간 성과를 확인하는 작은 기준이 꾸준함을 지켜 줘요.", "subtitle": "꾸준히 쌓아 가는 힘"}'),
('day', '戊寅', '{"code": "무인", "keywords": ["안정감", "책임감", "신중함"], "strengths": ["지속력", "신뢰"], "weaknesses": ["변화 부담", "고집"], "career": ["장기 프로젝트", "운영 관리"], "relationship": ["든든한 지지", "유연한 대화"], "intro": "한번 맡은 일은 쉽게 흔들리지 않고 버텨 내는 쪽에 가까워요. 빠른 성과보다 오래 지킬 수 있는 기반을 중요하게 느낄 수 있어요.", "strength_text": "복잡한 상황에서도 중심을 잡고 일을 꾸준히 이어 가는 힘이 있어요.", "caution_text": "익숙한 방식을 지키려는 마음이 새로운 가능성을 좁힐 수 있어요. 큰 변화보다 작은 실험부터 시작해 보세요.", "career_text": "여러 사람의 일을 안정적으로 연결하는 운영이나 긴 호흡의 프로젝트에서 역량이 드러나요.", "relationship_text": "곁에 있어 주는 것 자체로 마음을 표현하는 편이에요. 상대는 말로 확인받고 싶을 수 있으니 고마움을 조금 더 자주 전해 보세요.", "branch_text": "익숙한 곳을 벗어나 새로운 기회를 시험하고 싶은 마음도 함께 보여요. 시작한 일을 다듬는 시간까지 남겨 두면 좋아요.", "subtitle": "새로운 기회를 향한 의욕"}'),
('day', '己卯', '{"code": "기묘", "keywords": ["포용력", "현실감각", "꼼꼼함"], "strengths": ["지원", "관리 능력"], "weaknesses": ["과한 배려", "걱정"], "career": ["자원 관리", "실무 지원"], "relationship": ["생활 속 배려", "요구 전달"], "intro": "눈앞의 필요를 살피고 현실적으로 도움이 되는 방법을 찾는 쪽에 가까워요. 작은 것을 챙기며 전체를 안정시키는 모습이 보여요.", "strength_text": "흩어진 일과 자원을 정리하고 다른 사람이 제 몫을 할 수 있게 돕는 힘이 있어요.", "caution_text": "모두를 챙기려다 내 계획이 계속 밀릴 수 있어요. 도움을 주기 전에 가능한 범위를 먼저 정해 보세요.", "career_text": "세부 운영을 다듬거나 사람과 자원을 효율적으로 연결하는 일에서 장점을 살리기 좋아요.", "relationship_text": "거창한 말보다 생활 속 배려를 중요하게 여겨요. 나도 돌봄을 받을 수 있도록 원하는 것을 숨기지 않아도 괜찮아요.", "branch_text": "사람 사이의 분위기를 부드럽게 맞추려는 면도 함께 있어요. 편안한 관계 안에서 내 의견도 분명히 드러내 보세요.", "subtitle": "관계의 결을 읽는 감각"}'),
('day', '庚辰', '{"code": "경진", "keywords": ["결단력", "원칙", "도전"], "strengths": ["문제 해결", "실행"], "weaknesses": ["직설적 표현", "경직됨"], "career": ["문제 해결 업무", "체계 개선"], "relationship": ["명확한 약속", "부드러운 표현"], "intro": "문제가 보이면 핵심을 짚고 빠르게 정리하고 싶어 하는 쪽에 가까워요. 애매한 상태보다 기준이 분명한 상황에서 힘이 나기 쉬워요.", "strength_text": "어려운 결정을 피하지 않고 불필요한 과정을 줄이는 힘이 있어요.", "caution_text": "옳은 이야기도 너무 단단하게 전하면 상대가 마음을 닫을 수 있어요. 해결책을 말하기 전에 상대가 겪은 어려움을 먼저 들어 주세요.", "career_text": "엉킨 문제를 풀거나 비효율적인 체계를 개선하는 업무에서 역량이 살아나요.", "relationship_text": "말과 행동이 일치하는 관계를 편안하게 느껴요. 약속만큼 감정도 대화의 주제로 두면 관계가 더 부드러워져요.", "branch_text": "지금 모습에 머물기보다 더 큰 가능성을 마음에 품는 면이 있어요. 여러 계획 중 이번에 실현할 한 가지를 골라 보세요.", "subtitle": "변화를 담아내는 가능성"}'),
('day', '辛巳', '{"code": "신사", "keywords": ["정교함", "분석력", "미감"], "strengths": ["완성도", "집중력"], "weaknesses": ["완벽주의", "예민함"], "career": ["분석과 검수", "정밀한 표현"], "relationship": ["섬세한 취향", "기대 조율"], "intro": "작은 차이에서도 의미를 찾아내고 내 기준에 맞게 다듬는 쪽에 가까워요. 대충 넘어가기보다 완성도를 높일 때 만족감이 커질 수 있어요.", "strength_text": "세부의 오류를 찾고 결과물의 품질을 한 단계 올리는 힘이 있어요.", "caution_text": "완벽한 상태를 기다리면 시작이나 마무리가 늦어질 수 있어요. 이번 단계에 충분한 기준을 먼저 정해 보세요.", "career_text": "분석·검수나 정교한 감각을 표현하는 업무에서 집중력이 빛나기 좋아요.", "relationship_text": "세심하게 알아주는 말에 마음이 움직이는 편이에요. 상대도 같은 기준을 알 수 있도록 기대를 구체적으로 나눠 주세요.", "branch_text": "겉으로 보이는 것보다 안쪽의 이유를 알고 싶어 하는 면도 있어요. 충분히 살펴본 뒤에는 작은 실행으로 생각을 확인해 보세요.", "subtitle": "깊이 살펴보는 집중력"}'),
('day', '壬午', '{"code": "임오", "keywords": ["유연함", "탐구심", "넓은 시야"], "strengths": ["상황 판단", "연결 능력"], "weaknesses": ["방향 분산", "마무리 지연"], "career": ["정보 연결", "전략 수립"], "relationship": ["열린 대화", "일관된 표현"], "intro": "한 가지 답에 묶이기보다 여러 가능성을 살피는 쪽에 가까워요. 사람과 정보 사이의 흐름을 읽으며 새로운 길을 찾아가는 모습이에요.", "strength_text": "서로 떨어져 있던 생각을 연결하고 큰 흐름 속에서 선택지를 찾는 힘이 있어요.", "caution_text": "가능성이 많을수록 방향이 자주 바뀔 수 있어요. 지금 끝낼 일 하나를 고르면 넓은 시야가 실행으로 이어져요.", "career_text": "정보를 엮어 전략을 만들거나 다양한 사람을 연결하는 일에서 장점이 살아나요.", "relationship_text": "생각을 자유롭게 나눌 수 있는 관계를 편안하게 느껴요. 중요한 마음은 상황이 바뀌어도 일관되게 보여 주는 것이 좋아요.", "branch_text": "마음이 움직이는 순간 표현과 행동도 함께 커지기 쉬워요. 몰입할 일과 쉬어 갈 시간을 나눠 두면 열정을 오래 이어 갈 수 있어요.", "subtitle": "마음을 행동으로 옮기는 열기"}'),
('day', '癸未', '{"code": "계미", "keywords": ["직관", "관찰력", "신중함"], "strengths": ["공감", "깊은 사고"], "weaknesses": ["과도한 생각", "표현 주저"], "career": ["연구와 기록", "세밀한 상담"], "relationship": ["조용한 교감", "솔직한 요청"], "intro": "먼저 충분히 관찰하고 내 안에서 생각을 정리하는 쪽에 가까워요. 겉으로 드러난 말보다 미묘한 분위기를 세심하게 읽는 모습이에요.", "strength_text": "다른 사람이 지나친 단서를 모아 새로운 이해로 연결하는 힘이 있어요.", "caution_text": "생각이 많아질수록 아직 일어나지 않은 일까지 걱정하기 쉬워요. 확인된 사실과 추측을 나눠 적어 보세요.", "career_text": "깊이 탐구하고 기록하거나 상대의 이야기를 세심하게 듣는 일에서 역량을 살리기 좋아요.", "relationship_text": "조용히 통하는 관계를 소중히 여기지만 내 마음이 저절로 전달되지는 않아요. 작은 요청부터 솔직하게 표현해 보세요.", "branch_text": "내 일만큼 가까운 사람의 편안함을 살피는 면도 함께 있어요. 배려와 내 필요 사이의 균형을 잡아 보세요.", "subtitle": "주변을 살피는 다정함"}'),
('day', '甲申', '{"code": "갑신", "keywords": ["개척", "주도성", "성장"], "strengths": ["결단력", "책임감"], "weaknesses": ["완고함", "혼자 짊어짐"], "career": ["새로운 기획", "팀의 방향 설정"], "relationship": ["꾸준한 신뢰", "상대의 속도 존중"], "intro": "방향이 보이면 먼저 길을 내고 싶어 하는 쪽에 가까워요. 누군가 정해 준 답을 따르기보다 직접 기준을 세울 때 마음이 편할 수 있어요.", "strength_text": "시작이 막막한 순간에 해야 할 일을 정리하고 사람들을 이끄는 힘이 있어요.", "caution_text": "내가 책임져야 한다는 마음이 커지면 도움을 청하는 시기를 놓칠 수 있어요. 의견을 듣는 시간도 계획에 넣어 보세요.", "career_text": "새로운 일을 기획하거나 팀의 방향을 잡는 자리에서 역량을 드러내기 좋아요.", "relationship_text": "말보다 꾸준한 행동으로 신뢰를 쌓는 편이에요. 상대에게도 스스로 선택할 여유를 주면 관계가 한결 편안해져요.", "branch_text": "변화하는 상황에 맞춰 방법을 바꾸는 재치도 함께 보여요. 새로운 방법을 찾되 마무리 기준은 일정하게 두면 좋아요.", "subtitle": "상황에 맞춰 움직이는 재치"}'),
('day', '乙酉', '{"code": "을유", "keywords": ["적응력", "섬세함", "유연함"], "strengths": ["조율", "끈기"], "weaknesses": ["눈치 보기", "결정 미루기"], "career": ["협업과 조정", "세밀한 기획"], "relationship": ["세심한 배려", "분명한 의사 표현"], "intro": "주변의 작은 변화를 잘 읽고 상황에 맞게 방법을 바꾸는 쪽에 가까워요. 강하게 밀어붙이기보다 연결점을 찾으며 길을 만드는 모습이 보여요.", "strength_text": "서로 다른 의견 사이에서 접점을 찾고, 작은 일을 오래 다듬는 힘이 있어요.", "caution_text": "상대의 마음을 먼저 살피다 보면 정작 내 바람을 뒤로 미룰 수 있어요. 양보할 수 없는 기준을 하나 정해 두세요.", "career_text": "협업을 조율하거나 사용자의 마음을 세밀하게 읽는 일에서 장점이 살아나요.", "relationship_text": "작은 배려를 잘 기억하고 돌려주는 편이에요. 서운함이 쌓이기 전에 짧고 구체적으로 이야기하는 연습이 도움이 돼요.", "branch_text": "무엇을 하든 마지막 완성도를 확인하려는 면도 있어요. 잘된 부분부터 인정하면 스스로에게 지나치게 엄격해지는 것을 줄일 수 있어요.", "subtitle": "결과를 다듬는 감각"}'),
('day', '丙戌', '{"code": "병술", "keywords": ["활동적", "추진력", "표현력", "승부욕"], "strengths": ["실행력", "리더십"], "weaknesses": ["성급함", "과열"], "career": ["주도적인 업무", "전문성 표현"], "relationship": ["직접적인 감정 표현", "강한 자기주장 주의"], "intro": "생각만 오래 붙잡기보다 직접 움직이며 답을 찾는 쪽에 가까워요. 마음에 불이 붙은 일에는 존재감이 선명해지고, 주변에도 의욕을 전하는 모습이 보여요.", "strength_text": "망설이는 상황에서 첫걸음을 떼고 사람들을 움직이게 하는 힘이 있어요. 잘하는 것을 드러낼 기회가 생기면 자신감도 함께 살아나요.", "caution_text": "속도가 붙을수록 결론을 서두르거나 한 번에 너무 많은 일을 맡기 쉬워요. 중요한 결정 앞에서는 한 박자 쉬며 끝까지 가져갈 여력을 확인해 보세요.", "career_text": "스스로 방향을 잡는 업무나 기획·발표처럼 전문성을 눈에 보이게 표현하는 일에서 강점을 살리기 좋아요.", "relationship_text": "좋아하는 마음을 비교적 직접적으로 전하는 편이에요. 내 확신이 상대에게는 압박으로 느껴질 수 있으니, 말을 건넨 뒤 상대의 속도도 기다려 주세요.", "branch_text": "마음속 약속과 기준을 쉽게 버리지 않는 면도 함께 있어요. 원칙을 지키면서도 방법에는 여지를 남겨 보세요.", "subtitle": "기준을 지키는 성실함"}'),
('day', '丁亥', '{"code": "정해", "keywords": ["따뜻함", "집중력", "감수성"], "strengths": ["세심한 관찰", "몰입"], "weaknesses": ["걱정 쌓기", "감정 소모"], "career": ["전문 기술", "돌봄과 교육"], "relationship": ["깊은 교감", "감정의 경계"], "intro": "크게 드러내기보다 가까운 사람과 중요한 일에 오래 마음을 쓰는 쪽에 가까워요. 관심이 생긴 대상은 작은 차이까지 살피며 깊이를 더하는 모습이에요.", "strength_text": "작은 신호를 놓치지 않고 필요한 순간에 정교하게 힘을 쓰는 장점이 있어요.", "caution_text": "마음에 담아 둔 일이 많아지면 혼자 지칠 수 있어요. 신경 쓰이는 일을 적어 보고 내 몫과 상대의 몫을 나눠 보세요.", "career_text": "한 분야를 깊이 익히는 전문 업무나 누군가의 성장을 돕는 일에서 보람을 찾기 좋아요.", "relationship_text": "넓고 가벼운 만남보다 깊이 통하는 관계를 소중히 여겨요. 마음을 읽어 주기만 기다리기보다 필요한 도움을 말로 알려 주세요.", "branch_text": "당장 드러난 결과보다 사람과 상황을 넓게 이해하려는 면도 있어요. 충분히 생각한 뒤에는 내 선택을 구체적인 약속으로 만들어 보세요.", "subtitle": "넓게 이해하는 여유"}'),
('day', '戊子', '{"code": "무자", "keywords": ["안정감", "책임감", "신중함"], "strengths": ["지속력", "신뢰"], "weaknesses": ["변화 부담", "고집"], "career": ["장기 프로젝트", "운영 관리"], "relationship": ["든든한 지지", "유연한 대화"], "intro": "한번 맡은 일은 쉽게 흔들리지 않고 버텨 내는 쪽에 가까워요. 빠른 성과보다 오래 지킬 수 있는 기반을 중요하게 느낄 수 있어요.", "strength_text": "복잡한 상황에서도 중심을 잡고 일을 꾸준히 이어 가는 힘이 있어요.", "caution_text": "익숙한 방식을 지키려는 마음이 새로운 가능성을 좁힐 수 있어요. 큰 변화보다 작은 실험부터 시작해 보세요.", "career_text": "여러 사람의 일을 안정적으로 연결하는 운영이나 긴 호흡의 프로젝트에서 역량이 드러나요.", "relationship_text": "곁에 있어 주는 것 자체로 마음을 표현하는 편이에요. 상대는 말로 확인받고 싶을 수 있으니 고마움을 조금 더 자주 전해 보세요.", "branch_text": "겉으로 빠르게 드러내기보다 속으로 가능성을 비교하는 면도 함께 있어요. 결정을 내릴 시간을 확보하면 내 장점을 더 편하게 쓸 수 있어요.", "subtitle": "생각을 깊이 모으는 힘"}'),
('day', '己丑', '{"code": "기축", "keywords": ["포용력", "현실감각", "꼼꼼함"], "strengths": ["지원", "관리 능력"], "weaknesses": ["과한 배려", "걱정"], "career": ["자원 관리", "실무 지원"], "relationship": ["생활 속 배려", "요구 전달"], "intro": "눈앞의 필요를 살피고 현실적으로 도움이 되는 방법을 찾는 쪽에 가까워요. 작은 것을 챙기며 전체를 안정시키는 모습이 보여요.", "strength_text": "흩어진 일과 자원을 정리하고 다른 사람이 제 몫을 할 수 있게 돕는 힘이 있어요.", "caution_text": "모두를 챙기려다 내 계획이 계속 밀릴 수 있어요. 도움을 주기 전에 가능한 범위를 먼저 정해 보세요.", "career_text": "세부 운영을 다듬거나 사람과 자원을 효율적으로 연결하는 일에서 장점을 살리기 좋아요.", "relationship_text": "거창한 말보다 생활 속 배려를 중요하게 여겨요. 나도 돌봄을 받을 수 있도록 원하는 것을 숨기지 않아도 괜찮아요.", "branch_text": "결과가 바로 보이지 않아도 차근차근 쌓아 가려는 면이 함께 있어요. 중간 성과를 확인하는 작은 기준이 꾸준함을 지켜 줘요.", "subtitle": "꾸준히 쌓아 가는 힘"}'),
('day', '庚寅', '{"code": "경인", "keywords": ["결단력", "원칙", "도전"], "strengths": ["문제 해결", "실행"], "weaknesses": ["직설적 표현", "경직됨"], "career": ["문제 해결 업무", "체계 개선"], "relationship": ["명확한 약속", "부드러운 표현"], "intro": "문제가 보이면 핵심을 짚고 빠르게 정리하고 싶어 하는 쪽에 가까워요. 애매한 상태보다 기준이 분명한 상황에서 힘이 나기 쉬워요.", "strength_text": "어려운 결정을 피하지 않고 불필요한 과정을 줄이는 힘이 있어요.", "caution_text": "옳은 이야기도 너무 단단하게 전하면 상대가 마음을 닫을 수 있어요. 해결책을 말하기 전에 상대가 겪은 어려움을 먼저 들어 주세요.", "career_text": "엉킨 문제를 풀거나 비효율적인 체계를 개선하는 업무에서 역량이 살아나요.", "relationship_text": "말과 행동이 일치하는 관계를 편안하게 느껴요. 약속만큼 감정도 대화의 주제로 두면 관계가 더 부드러워져요.", "branch_text": "익숙한 곳을 벗어나 새로운 기회를 시험하고 싶은 마음도 함께 보여요. 시작한 일을 다듬는 시간까지 남겨 두면 좋아요.", "subtitle": "새로운 기회를 향한 의욕"}'),
('day', '辛卯', '{"code": "신묘", "keywords": ["정교함", "분석력", "미감"], "strengths": ["완성도", "집중력"], "weaknesses": ["완벽주의", "예민함"], "career": ["분석과 검수", "정밀한 표현"], "relationship": ["섬세한 취향", "기대 조율"], "intro": "작은 차이에서도 의미를 찾아내고 내 기준에 맞게 다듬는 쪽에 가까워요. 대충 넘어가기보다 완성도를 높일 때 만족감이 커질 수 있어요.", "strength_text": "세부의 오류를 찾고 결과물의 품질을 한 단계 올리는 힘이 있어요.", "caution_text": "완벽한 상태를 기다리면 시작이나 마무리가 늦어질 수 있어요. 이번 단계에 충분한 기준을 먼저 정해 보세요.", "career_text": "분석·검수나 정교한 감각을 표현하는 업무에서 집중력이 빛나기 좋아요.", "relationship_text": "세심하게 알아주는 말에 마음이 움직이는 편이에요. 상대도 같은 기준을 알 수 있도록 기대를 구체적으로 나눠 주세요.", "branch_text": "사람 사이의 분위기를 부드럽게 맞추려는 면도 함께 있어요. 편안한 관계 안에서 내 의견도 분명히 드러내 보세요.", "subtitle": "관계의 결을 읽는 감각"}'),
('day', '壬辰', '{"code": "임진", "keywords": ["유연함", "탐구심", "넓은 시야"], "strengths": ["상황 판단", "연결 능력"], "weaknesses": ["방향 분산", "마무리 지연"], "career": ["정보 연결", "전략 수립"], "relationship": ["열린 대화", "일관된 표현"], "intro": "한 가지 답에 묶이기보다 여러 가능성을 살피는 쪽에 가까워요. 사람과 정보 사이의 흐름을 읽으며 새로운 길을 찾아가는 모습이에요.", "strength_text": "서로 떨어져 있던 생각을 연결하고 큰 흐름 속에서 선택지를 찾는 힘이 있어요.", "caution_text": "가능성이 많을수록 방향이 자주 바뀔 수 있어요. 지금 끝낼 일 하나를 고르면 넓은 시야가 실행으로 이어져요.", "career_text": "정보를 엮어 전략을 만들거나 다양한 사람을 연결하는 일에서 장점이 살아나요.", "relationship_text": "생각을 자유롭게 나눌 수 있는 관계를 편안하게 느껴요. 중요한 마음은 상황이 바뀌어도 일관되게 보여 주는 것이 좋아요.", "branch_text": "지금 모습에 머물기보다 더 큰 가능성을 마음에 품는 면이 있어요. 여러 계획 중 이번에 실현할 한 가지를 골라 보세요.", "subtitle": "변화를 담아내는 가능성"}'),
('day', '癸巳', '{"code": "계사", "keywords": ["직관", "관찰력", "신중함"], "strengths": ["공감", "깊은 사고"], "weaknesses": ["과도한 생각", "표현 주저"], "career": ["연구와 기록", "세밀한 상담"], "relationship": ["조용한 교감", "솔직한 요청"], "intro": "먼저 충분히 관찰하고 내 안에서 생각을 정리하는 쪽에 가까워요. 겉으로 드러난 말보다 미묘한 분위기를 세심하게 읽는 모습이에요.", "strength_text": "다른 사람이 지나친 단서를 모아 새로운 이해로 연결하는 힘이 있어요.", "caution_text": "생각이 많아질수록 아직 일어나지 않은 일까지 걱정하기 쉬워요. 확인된 사실과 추측을 나눠 적어 보세요.", "career_text": "깊이 탐구하고 기록하거나 상대의 이야기를 세심하게 듣는 일에서 역량을 살리기 좋아요.", "relationship_text": "조용히 통하는 관계를 소중히 여기지만 내 마음이 저절로 전달되지는 않아요. 작은 요청부터 솔직하게 표현해 보세요.", "branch_text": "겉으로 보이는 것보다 안쪽의 이유를 알고 싶어 하는 면도 있어요. 충분히 살펴본 뒤에는 작은 실행으로 생각을 확인해 보세요.", "subtitle": "깊이 살펴보는 집중력"}'),
('day', '甲午', '{"code": "갑오", "keywords": ["개척", "주도성", "성장"], "strengths": ["결단력", "책임감"], "weaknesses": ["완고함", "혼자 짊어짐"], "career": ["새로운 기획", "팀의 방향 설정"], "relationship": ["꾸준한 신뢰", "상대의 속도 존중"], "intro": "방향이 보이면 먼저 길을 내고 싶어 하는 쪽에 가까워요. 누군가 정해 준 답을 따르기보다 직접 기준을 세울 때 마음이 편할 수 있어요.", "strength_text": "시작이 막막한 순간에 해야 할 일을 정리하고 사람들을 이끄는 힘이 있어요.", "caution_text": "내가 책임져야 한다는 마음이 커지면 도움을 청하는 시기를 놓칠 수 있어요. 의견을 듣는 시간도 계획에 넣어 보세요.", "career_text": "새로운 일을 기획하거나 팀의 방향을 잡는 자리에서 역량을 드러내기 좋아요.", "relationship_text": "말보다 꾸준한 행동으로 신뢰를 쌓는 편이에요. 상대에게도 스스로 선택할 여유를 주면 관계가 한결 편안해져요.", "branch_text": "마음이 움직이는 순간 표현과 행동도 함께 커지기 쉬워요. 몰입할 일과 쉬어 갈 시간을 나눠 두면 열정을 오래 이어 갈 수 있어요.", "subtitle": "마음을 행동으로 옮기는 열기"}'),
('day', '乙未', '{"code": "을미", "keywords": ["적응력", "섬세함", "유연함"], "strengths": ["조율", "끈기"], "weaknesses": ["눈치 보기", "결정 미루기"], "career": ["협업과 조정", "세밀한 기획"], "relationship": ["세심한 배려", "분명한 의사 표현"], "intro": "주변의 작은 변화를 잘 읽고 상황에 맞게 방법을 바꾸는 쪽에 가까워요. 강하게 밀어붙이기보다 연결점을 찾으며 길을 만드는 모습이 보여요.", "strength_text": "서로 다른 의견 사이에서 접점을 찾고, 작은 일을 오래 다듬는 힘이 있어요.", "caution_text": "상대의 마음을 먼저 살피다 보면 정작 내 바람을 뒤로 미룰 수 있어요. 양보할 수 없는 기준을 하나 정해 두세요.", "career_text": "협업을 조율하거나 사용자의 마음을 세밀하게 읽는 일에서 장점이 살아나요.", "relationship_text": "작은 배려를 잘 기억하고 돌려주는 편이에요. 서운함이 쌓이기 전에 짧고 구체적으로 이야기하는 연습이 도움이 돼요.", "branch_text": "내 일만큼 가까운 사람의 편안함을 살피는 면도 함께 있어요. 배려와 내 필요 사이의 균형을 잡아 보세요.", "subtitle": "주변을 살피는 다정함"}'),
('day', '丙申', '{"code": "병신", "keywords": ["활동적", "추진력", "표현력", "승부욕"], "strengths": ["실행력", "리더십"], "weaknesses": ["성급함", "과열"], "career": ["주도적인 업무", "전문성 표현"], "relationship": ["직접적인 감정 표현", "강한 자기주장 주의"], "intro": "생각만 오래 붙잡기보다 직접 움직이며 답을 찾는 쪽에 가까워요. 마음에 불이 붙은 일에는 존재감이 선명해지고, 주변에도 의욕을 전하는 모습이 보여요.", "strength_text": "망설이는 상황에서 첫걸음을 떼고 사람들을 움직이게 하는 힘이 있어요. 잘하는 것을 드러낼 기회가 생기면 자신감도 함께 살아나요.", "caution_text": "속도가 붙을수록 결론을 서두르거나 한 번에 너무 많은 일을 맡기 쉬워요. 중요한 결정 앞에서는 한 박자 쉬며 끝까지 가져갈 여력을 확인해 보세요.", "career_text": "스스로 방향을 잡는 업무나 기획·발표처럼 전문성을 눈에 보이게 표현하는 일에서 강점을 살리기 좋아요.", "relationship_text": "좋아하는 마음을 비교적 직접적으로 전하는 편이에요. 내 확신이 상대에게는 압박으로 느껴질 수 있으니, 말을 건넨 뒤 상대의 속도도 기다려 주세요.", "branch_text": "변화하는 상황에 맞춰 방법을 바꾸는 재치도 함께 보여요. 새로운 방법을 찾되 마무리 기준은 일정하게 두면 좋아요.", "subtitle": "상황에 맞춰 움직이는 재치"}'),
('day', '丁酉', '{"code": "정유", "keywords": ["따뜻함", "집중력", "감수성"], "strengths": ["세심한 관찰", "몰입"], "weaknesses": ["걱정 쌓기", "감정 소모"], "career": ["전문 기술", "돌봄과 교육"], "relationship": ["깊은 교감", "감정의 경계"], "intro": "크게 드러내기보다 가까운 사람과 중요한 일에 오래 마음을 쓰는 쪽에 가까워요. 관심이 생긴 대상은 작은 차이까지 살피며 깊이를 더하는 모습이에요.", "strength_text": "작은 신호를 놓치지 않고 필요한 순간에 정교하게 힘을 쓰는 장점이 있어요.", "caution_text": "마음에 담아 둔 일이 많아지면 혼자 지칠 수 있어요. 신경 쓰이는 일을 적어 보고 내 몫과 상대의 몫을 나눠 보세요.", "career_text": "한 분야를 깊이 익히는 전문 업무나 누군가의 성장을 돕는 일에서 보람을 찾기 좋아요.", "relationship_text": "넓고 가벼운 만남보다 깊이 통하는 관계를 소중히 여겨요. 마음을 읽어 주기만 기다리기보다 필요한 도움을 말로 알려 주세요.", "branch_text": "무엇을 하든 마지막 완성도를 확인하려는 면도 있어요. 잘된 부분부터 인정하면 스스로에게 지나치게 엄격해지는 것을 줄일 수 있어요.", "subtitle": "결과를 다듬는 감각"}'),
('day', '戊戌', '{"code": "무술", "keywords": ["안정감", "책임감", "신중함"], "strengths": ["지속력", "신뢰"], "weaknesses": ["변화 부담", "고집"], "career": ["장기 프로젝트", "운영 관리"], "relationship": ["든든한 지지", "유연한 대화"], "intro": "한번 맡은 일은 쉽게 흔들리지 않고 버텨 내는 쪽에 가까워요. 빠른 성과보다 오래 지킬 수 있는 기반을 중요하게 느낄 수 있어요.", "strength_text": "복잡한 상황에서도 중심을 잡고 일을 꾸준히 이어 가는 힘이 있어요.", "caution_text": "익숙한 방식을 지키려는 마음이 새로운 가능성을 좁힐 수 있어요. 큰 변화보다 작은 실험부터 시작해 보세요.", "career_text": "여러 사람의 일을 안정적으로 연결하는 운영이나 긴 호흡의 프로젝트에서 역량이 드러나요.", "relationship_text": "곁에 있어 주는 것 자체로 마음을 표현하는 편이에요. 상대는 말로 확인받고 싶을 수 있으니 고마움을 조금 더 자주 전해 보세요.", "branch_text": "마음속 약속과 기준을 쉽게 버리지 않는 면도 함께 있어요. 원칙을 지키면서도 방법에는 여지를 남겨 보세요.", "subtitle": "기준을 지키는 성실함"}'),
('day', '己亥', '{"code": "기해", "keywords": ["포용력", "현실감각", "꼼꼼함"], "strengths": ["지원", "관리 능력"], "weaknesses": ["과한 배려", "걱정"], "career": ["자원 관리", "실무 지원"], "relationship": ["생활 속 배려", "요구 전달"], "intro": "눈앞의 필요를 살피고 현실적으로 도움이 되는 방법을 찾는 쪽에 가까워요. 작은 것을 챙기며 전체를 안정시키는 모습이 보여요.", "strength_text": "흩어진 일과 자원을 정리하고 다른 사람이 제 몫을 할 수 있게 돕는 힘이 있어요.", "caution_text": "모두를 챙기려다 내 계획이 계속 밀릴 수 있어요. 도움을 주기 전에 가능한 범위를 먼저 정해 보세요.", "career_text": "세부 운영을 다듬거나 사람과 자원을 효율적으로 연결하는 일에서 장점을 살리기 좋아요.", "relationship_text": "거창한 말보다 생활 속 배려를 중요하게 여겨요. 나도 돌봄을 받을 수 있도록 원하는 것을 숨기지 않아도 괜찮아요.", "branch_text": "당장 드러난 결과보다 사람과 상황을 넓게 이해하려는 면도 있어요. 충분히 생각한 뒤에는 내 선택을 구체적인 약속으로 만들어 보세요.", "subtitle": "넓게 이해하는 여유"}'),
('day', '庚子', '{"code": "경자", "keywords": ["결단력", "원칙", "도전"], "strengths": ["문제 해결", "실행"], "weaknesses": ["직설적 표현", "경직됨"], "career": ["문제 해결 업무", "체계 개선"], "relationship": ["명확한 약속", "부드러운 표현"], "intro": "문제가 보이면 핵심을 짚고 빠르게 정리하고 싶어 하는 쪽에 가까워요. 애매한 상태보다 기준이 분명한 상황에서 힘이 나기 쉬워요.", "strength_text": "어려운 결정을 피하지 않고 불필요한 과정을 줄이는 힘이 있어요.", "caution_text": "옳은 이야기도 너무 단단하게 전하면 상대가 마음을 닫을 수 있어요. 해결책을 말하기 전에 상대가 겪은 어려움을 먼저 들어 주세요.", "career_text": "엉킨 문제를 풀거나 비효율적인 체계를 개선하는 업무에서 역량이 살아나요.", "relationship_text": "말과 행동이 일치하는 관계를 편안하게 느껴요. 약속만큼 감정도 대화의 주제로 두면 관계가 더 부드러워져요.", "branch_text": "겉으로 빠르게 드러내기보다 속으로 가능성을 비교하는 면도 함께 있어요. 결정을 내릴 시간을 확보하면 내 장점을 더 편하게 쓸 수 있어요.", "subtitle": "생각을 깊이 모으는 힘"}'),
('day', '辛丑', '{"code": "신축", "keywords": ["정교함", "분석력", "미감"], "strengths": ["완성도", "집중력"], "weaknesses": ["완벽주의", "예민함"], "career": ["분석과 검수", "정밀한 표현"], "relationship": ["섬세한 취향", "기대 조율"], "intro": "작은 차이에서도 의미를 찾아내고 내 기준에 맞게 다듬는 쪽에 가까워요. 대충 넘어가기보다 완성도를 높일 때 만족감이 커질 수 있어요.", "strength_text": "세부의 오류를 찾고 결과물의 품질을 한 단계 올리는 힘이 있어요.", "caution_text": "완벽한 상태를 기다리면 시작이나 마무리가 늦어질 수 있어요. 이번 단계에 충분한 기준을 먼저 정해 보세요.", "career_text": "분석·검수나 정교한 감각을 표현하는 업무에서 집중력이 빛나기 좋아요.", "relationship_text": "세심하게 알아주는 말에 마음이 움직이는 편이에요. 상대도 같은 기준을 알 수 있도록 기대를 구체적으로 나눠 주세요.", "branch_text": "결과가 바로 보이지 않아도 차근차근 쌓아 가려는 면이 함께 있어요. 중간 성과를 확인하는 작은 기준이 꾸준함을 지켜 줘요.", "subtitle": "꾸준히 쌓아 가는 힘"}'),
('day', '壬寅', '{"code": "임인", "keywords": ["유연함", "탐구심", "넓은 시야"], "strengths": ["상황 판단", "연결 능력"], "weaknesses": ["방향 분산", "마무리 지연"], "career": ["정보 연결", "전략 수립"], "relationship": ["열린 대화", "일관된 표현"], "intro": "한 가지 답에 묶이기보다 여러 가능성을 살피는 쪽에 가까워요. 사람과 정보 사이의 흐름을 읽으며 새로운 길을 찾아가는 모습이에요.", "strength_text": "서로 떨어져 있던 생각을 연결하고 큰 흐름 속에서 선택지를 찾는 힘이 있어요.", "caution_text": "가능성이 많을수록 방향이 자주 바뀔 수 있어요. 지금 끝낼 일 하나를 고르면 넓은 시야가 실행으로 이어져요.", "career_text": "정보를 엮어 전략을 만들거나 다양한 사람을 연결하는 일에서 장점이 살아나요.", "relationship_text": "생각을 자유롭게 나눌 수 있는 관계를 편안하게 느껴요. 중요한 마음은 상황이 바뀌어도 일관되게 보여 주는 것이 좋아요.", "branch_text": "익숙한 곳을 벗어나 새로운 기회를 시험하고 싶은 마음도 함께 보여요. 시작한 일을 다듬는 시간까지 남겨 두면 좋아요.", "subtitle": "새로운 기회를 향한 의욕"}'),
('day', '癸卯', '{"code": "계묘", "keywords": ["직관", "관찰력", "신중함"], "strengths": ["공감", "깊은 사고"], "weaknesses": ["과도한 생각", "표현 주저"], "career": ["연구와 기록", "세밀한 상담"], "relationship": ["조용한 교감", "솔직한 요청"], "intro": "먼저 충분히 관찰하고 내 안에서 생각을 정리하는 쪽에 가까워요. 겉으로 드러난 말보다 미묘한 분위기를 세심하게 읽는 모습이에요.", "strength_text": "다른 사람이 지나친 단서를 모아 새로운 이해로 연결하는 힘이 있어요.", "caution_text": "생각이 많아질수록 아직 일어나지 않은 일까지 걱정하기 쉬워요. 확인된 사실과 추측을 나눠 적어 보세요.", "career_text": "깊이 탐구하고 기록하거나 상대의 이야기를 세심하게 듣는 일에서 역량을 살리기 좋아요.", "relationship_text": "조용히 통하는 관계를 소중히 여기지만 내 마음이 저절로 전달되지는 않아요. 작은 요청부터 솔직하게 표현해 보세요.", "branch_text": "사람 사이의 분위기를 부드럽게 맞추려는 면도 함께 있어요. 편안한 관계 안에서 내 의견도 분명히 드러내 보세요.", "subtitle": "관계의 결을 읽는 감각"}'),
('day', '甲辰', '{"code": "갑진", "keywords": ["개척", "주도성", "성장"], "strengths": ["결단력", "책임감"], "weaknesses": ["완고함", "혼자 짊어짐"], "career": ["새로운 기획", "팀의 방향 설정"], "relationship": ["꾸준한 신뢰", "상대의 속도 존중"], "intro": "방향이 보이면 먼저 길을 내고 싶어 하는 쪽에 가까워요. 누군가 정해 준 답을 따르기보다 직접 기준을 세울 때 마음이 편할 수 있어요.", "strength_text": "시작이 막막한 순간에 해야 할 일을 정리하고 사람들을 이끄는 힘이 있어요.", "caution_text": "내가 책임져야 한다는 마음이 커지면 도움을 청하는 시기를 놓칠 수 있어요. 의견을 듣는 시간도 계획에 넣어 보세요.", "career_text": "새로운 일을 기획하거나 팀의 방향을 잡는 자리에서 역량을 드러내기 좋아요.", "relationship_text": "말보다 꾸준한 행동으로 신뢰를 쌓는 편이에요. 상대에게도 스스로 선택할 여유를 주면 관계가 한결 편안해져요.", "branch_text": "지금 모습에 머물기보다 더 큰 가능성을 마음에 품는 면이 있어요. 여러 계획 중 이번에 실현할 한 가지를 골라 보세요.", "subtitle": "변화를 담아내는 가능성"}'),
('day', '乙巳', '{"code": "을사", "keywords": ["적응력", "섬세함", "유연함"], "strengths": ["조율", "끈기"], "weaknesses": ["눈치 보기", "결정 미루기"], "career": ["협업과 조정", "세밀한 기획"], "relationship": ["세심한 배려", "분명한 의사 표현"], "intro": "주변의 작은 변화를 잘 읽고 상황에 맞게 방법을 바꾸는 쪽에 가까워요. 강하게 밀어붙이기보다 연결점을 찾으며 길을 만드는 모습이 보여요.", "strength_text": "서로 다른 의견 사이에서 접점을 찾고, 작은 일을 오래 다듬는 힘이 있어요.", "caution_text": "상대의 마음을 먼저 살피다 보면 정작 내 바람을 뒤로 미룰 수 있어요. 양보할 수 없는 기준을 하나 정해 두세요.", "career_text": "협업을 조율하거나 사용자의 마음을 세밀하게 읽는 일에서 장점이 살아나요.", "relationship_text": "작은 배려를 잘 기억하고 돌려주는 편이에요. 서운함이 쌓이기 전에 짧고 구체적으로 이야기하는 연습이 도움이 돼요.", "branch_text": "겉으로 보이는 것보다 안쪽의 이유를 알고 싶어 하는 면도 있어요. 충분히 살펴본 뒤에는 작은 실행으로 생각을 확인해 보세요.", "subtitle": "깊이 살펴보는 집중력"}'),
('day', '丙午', '{"code": "병오", "keywords": ["활동적", "추진력", "표현력", "승부욕"], "strengths": ["실행력", "리더십"], "weaknesses": ["성급함", "과열"], "career": ["주도적인 업무", "전문성 표현"], "relationship": ["직접적인 감정 표현", "강한 자기주장 주의"], "intro": "생각만 오래 붙잡기보다 직접 움직이며 답을 찾는 쪽에 가까워요. 마음에 불이 붙은 일에는 존재감이 선명해지고, 주변에도 의욕을 전하는 모습이 보여요.", "strength_text": "망설이는 상황에서 첫걸음을 떼고 사람들을 움직이게 하는 힘이 있어요. 잘하는 것을 드러낼 기회가 생기면 자신감도 함께 살아나요.", "caution_text": "속도가 붙을수록 결론을 서두르거나 한 번에 너무 많은 일을 맡기 쉬워요. 중요한 결정 앞에서는 한 박자 쉬며 끝까지 가져갈 여력을 확인해 보세요.", "career_text": "스스로 방향을 잡는 업무나 기획·발표처럼 전문성을 눈에 보이게 표현하는 일에서 강점을 살리기 좋아요.", "relationship_text": "좋아하는 마음을 비교적 직접적으로 전하는 편이에요. 내 확신이 상대에게는 압박으로 느껴질 수 있으니, 말을 건넨 뒤 상대의 속도도 기다려 주세요.", "branch_text": "마음이 움직이는 순간 표현과 행동도 함께 커지기 쉬워요. 몰입할 일과 쉬어 갈 시간을 나눠 두면 열정을 오래 이어 갈 수 있어요.", "subtitle": "마음을 행동으로 옮기는 열기"}'),
('day', '丁未', '{"code": "정미", "keywords": ["따뜻함", "집중력", "감수성"], "strengths": ["세심한 관찰", "몰입"], "weaknesses": ["걱정 쌓기", "감정 소모"], "career": ["전문 기술", "돌봄과 교육"], "relationship": ["깊은 교감", "감정의 경계"], "intro": "크게 드러내기보다 가까운 사람과 중요한 일에 오래 마음을 쓰는 쪽에 가까워요. 관심이 생긴 대상은 작은 차이까지 살피며 깊이를 더하는 모습이에요.", "strength_text": "작은 신호를 놓치지 않고 필요한 순간에 정교하게 힘을 쓰는 장점이 있어요.", "caution_text": "마음에 담아 둔 일이 많아지면 혼자 지칠 수 있어요. 신경 쓰이는 일을 적어 보고 내 몫과 상대의 몫을 나눠 보세요.", "career_text": "한 분야를 깊이 익히는 전문 업무나 누군가의 성장을 돕는 일에서 보람을 찾기 좋아요.", "relationship_text": "넓고 가벼운 만남보다 깊이 통하는 관계를 소중히 여겨요. 마음을 읽어 주기만 기다리기보다 필요한 도움을 말로 알려 주세요.", "branch_text": "내 일만큼 가까운 사람의 편안함을 살피는 면도 함께 있어요. 배려와 내 필요 사이의 균형을 잡아 보세요.", "subtitle": "주변을 살피는 다정함"}'),
('day', '戊申', '{"code": "무신", "keywords": ["안정감", "책임감", "신중함"], "strengths": ["지속력", "신뢰"], "weaknesses": ["변화 부담", "고집"], "career": ["장기 프로젝트", "운영 관리"], "relationship": ["든든한 지지", "유연한 대화"], "intro": "한번 맡은 일은 쉽게 흔들리지 않고 버텨 내는 쪽에 가까워요. 빠른 성과보다 오래 지킬 수 있는 기반을 중요하게 느낄 수 있어요.", "strength_text": "복잡한 상황에서도 중심을 잡고 일을 꾸준히 이어 가는 힘이 있어요.", "caution_text": "익숙한 방식을 지키려는 마음이 새로운 가능성을 좁힐 수 있어요. 큰 변화보다 작은 실험부터 시작해 보세요.", "career_text": "여러 사람의 일을 안정적으로 연결하는 운영이나 긴 호흡의 프로젝트에서 역량이 드러나요.", "relationship_text": "곁에 있어 주는 것 자체로 마음을 표현하는 편이에요. 상대는 말로 확인받고 싶을 수 있으니 고마움을 조금 더 자주 전해 보세요.", "branch_text": "변화하는 상황에 맞춰 방법을 바꾸는 재치도 함께 보여요. 새로운 방법을 찾되 마무리 기준은 일정하게 두면 좋아요.", "subtitle": "상황에 맞춰 움직이는 재치"}'),
('day', '己酉', '{"code": "기유", "keywords": ["포용력", "현실감각", "꼼꼼함"], "strengths": ["지원", "관리 능력"], "weaknesses": ["과한 배려", "걱정"], "career": ["자원 관리", "실무 지원"], "relationship": ["생활 속 배려", "요구 전달"], "intro": "눈앞의 필요를 살피고 현실적으로 도움이 되는 방법을 찾는 쪽에 가까워요. 작은 것을 챙기며 전체를 안정시키는 모습이 보여요.", "strength_text": "흩어진 일과 자원을 정리하고 다른 사람이 제 몫을 할 수 있게 돕는 힘이 있어요.", "caution_text": "모두를 챙기려다 내 계획이 계속 밀릴 수 있어요. 도움을 주기 전에 가능한 범위를 먼저 정해 보세요.", "career_text": "세부 운영을 다듬거나 사람과 자원을 효율적으로 연결하는 일에서 장점을 살리기 좋아요.", "relationship_text": "거창한 말보다 생활 속 배려를 중요하게 여겨요. 나도 돌봄을 받을 수 있도록 원하는 것을 숨기지 않아도 괜찮아요.", "branch_text": "무엇을 하든 마지막 완성도를 확인하려는 면도 있어요. 잘된 부분부터 인정하면 스스로에게 지나치게 엄격해지는 것을 줄일 수 있어요.", "subtitle": "결과를 다듬는 감각"}'),
('day', '庚戌', '{"code": "경술", "keywords": ["결단력", "원칙", "도전"], "strengths": ["문제 해결", "실행"], "weaknesses": ["직설적 표현", "경직됨"], "career": ["문제 해결 업무", "체계 개선"], "relationship": ["명확한 약속", "부드러운 표현"], "intro": "문제가 보이면 핵심을 짚고 빠르게 정리하고 싶어 하는 쪽에 가까워요. 애매한 상태보다 기준이 분명한 상황에서 힘이 나기 쉬워요.", "strength_text": "어려운 결정을 피하지 않고 불필요한 과정을 줄이는 힘이 있어요.", "caution_text": "옳은 이야기도 너무 단단하게 전하면 상대가 마음을 닫을 수 있어요. 해결책을 말하기 전에 상대가 겪은 어려움을 먼저 들어 주세요.", "career_text": "엉킨 문제를 풀거나 비효율적인 체계를 개선하는 업무에서 역량이 살아나요.", "relationship_text": "말과 행동이 일치하는 관계를 편안하게 느껴요. 약속만큼 감정도 대화의 주제로 두면 관계가 더 부드러워져요.", "branch_text": "마음속 약속과 기준을 쉽게 버리지 않는 면도 함께 있어요. 원칙을 지키면서도 방법에는 여지를 남겨 보세요.", "subtitle": "기준을 지키는 성실함"}'),
('day', '辛亥', '{"code": "신해", "keywords": ["정교함", "분석력", "미감"], "strengths": ["완성도", "집중력"], "weaknesses": ["완벽주의", "예민함"], "career": ["분석과 검수", "정밀한 표현"], "relationship": ["섬세한 취향", "기대 조율"], "intro": "작은 차이에서도 의미를 찾아내고 내 기준에 맞게 다듬는 쪽에 가까워요. 대충 넘어가기보다 완성도를 높일 때 만족감이 커질 수 있어요.", "strength_text": "세부의 오류를 찾고 결과물의 품질을 한 단계 올리는 힘이 있어요.", "caution_text": "완벽한 상태를 기다리면 시작이나 마무리가 늦어질 수 있어요. 이번 단계에 충분한 기준을 먼저 정해 보세요.", "career_text": "분석·검수나 정교한 감각을 표현하는 업무에서 집중력이 빛나기 좋아요.", "relationship_text": "세심하게 알아주는 말에 마음이 움직이는 편이에요. 상대도 같은 기준을 알 수 있도록 기대를 구체적으로 나눠 주세요.", "branch_text": "당장 드러난 결과보다 사람과 상황을 넓게 이해하려는 면도 있어요. 충분히 생각한 뒤에는 내 선택을 구체적인 약속으로 만들어 보세요.", "subtitle": "넓게 이해하는 여유"}'),
('day', '壬子', '{"code": "임자", "keywords": ["유연함", "탐구심", "넓은 시야"], "strengths": ["상황 판단", "연결 능력"], "weaknesses": ["방향 분산", "마무리 지연"], "career": ["정보 연결", "전략 수립"], "relationship": ["열린 대화", "일관된 표현"], "intro": "한 가지 답에 묶이기보다 여러 가능성을 살피는 쪽에 가까워요. 사람과 정보 사이의 흐름을 읽으며 새로운 길을 찾아가는 모습이에요.", "strength_text": "서로 떨어져 있던 생각을 연결하고 큰 흐름 속에서 선택지를 찾는 힘이 있어요.", "caution_text": "가능성이 많을수록 방향이 자주 바뀔 수 있어요. 지금 끝낼 일 하나를 고르면 넓은 시야가 실행으로 이어져요.", "career_text": "정보를 엮어 전략을 만들거나 다양한 사람을 연결하는 일에서 장점이 살아나요.", "relationship_text": "생각을 자유롭게 나눌 수 있는 관계를 편안하게 느껴요. 중요한 마음은 상황이 바뀌어도 일관되게 보여 주는 것이 좋아요.", "branch_text": "겉으로 빠르게 드러내기보다 속으로 가능성을 비교하는 면도 함께 있어요. 결정을 내릴 시간을 확보하면 내 장점을 더 편하게 쓸 수 있어요.", "subtitle": "생각을 깊이 모으는 힘"}'),
('day', '癸丑', '{"code": "계축", "keywords": ["직관", "관찰력", "신중함"], "strengths": ["공감", "깊은 사고"], "weaknesses": ["과도한 생각", "표현 주저"], "career": ["연구와 기록", "세밀한 상담"], "relationship": ["조용한 교감", "솔직한 요청"], "intro": "먼저 충분히 관찰하고 내 안에서 생각을 정리하는 쪽에 가까워요. 겉으로 드러난 말보다 미묘한 분위기를 세심하게 읽는 모습이에요.", "strength_text": "다른 사람이 지나친 단서를 모아 새로운 이해로 연결하는 힘이 있어요.", "caution_text": "생각이 많아질수록 아직 일어나지 않은 일까지 걱정하기 쉬워요. 확인된 사실과 추측을 나눠 적어 보세요.", "career_text": "깊이 탐구하고 기록하거나 상대의 이야기를 세심하게 듣는 일에서 역량을 살리기 좋아요.", "relationship_text": "조용히 통하는 관계를 소중히 여기지만 내 마음이 저절로 전달되지는 않아요. 작은 요청부터 솔직하게 표현해 보세요.", "branch_text": "결과가 바로 보이지 않아도 차근차근 쌓아 가려는 면이 함께 있어요. 중간 성과를 확인하는 작은 기준이 꾸준함을 지켜 줘요.", "subtitle": "꾸준히 쌓아 가는 힘"}'),
('day', '甲寅', '{"code": "갑인", "keywords": ["개척", "주도성", "성장"], "strengths": ["결단력", "책임감"], "weaknesses": ["완고함", "혼자 짊어짐"], "career": ["새로운 기획", "팀의 방향 설정"], "relationship": ["꾸준한 신뢰", "상대의 속도 존중"], "intro": "방향이 보이면 먼저 길을 내고 싶어 하는 쪽에 가까워요. 누군가 정해 준 답을 따르기보다 직접 기준을 세울 때 마음이 편할 수 있어요.", "strength_text": "시작이 막막한 순간에 해야 할 일을 정리하고 사람들을 이끄는 힘이 있어요.", "caution_text": "내가 책임져야 한다는 마음이 커지면 도움을 청하는 시기를 놓칠 수 있어요. 의견을 듣는 시간도 계획에 넣어 보세요.", "career_text": "새로운 일을 기획하거나 팀의 방향을 잡는 자리에서 역량을 드러내기 좋아요.", "relationship_text": "말보다 꾸준한 행동으로 신뢰를 쌓는 편이에요. 상대에게도 스스로 선택할 여유를 주면 관계가 한결 편안해져요.", "branch_text": "익숙한 곳을 벗어나 새로운 기회를 시험하고 싶은 마음도 함께 보여요. 시작한 일을 다듬는 시간까지 남겨 두면 좋아요.", "subtitle": "새로운 기회를 향한 의욕"}'),
('day', '乙卯', '{"code": "을묘", "keywords": ["적응력", "섬세함", "유연함"], "strengths": ["조율", "끈기"], "weaknesses": ["눈치 보기", "결정 미루기"], "career": ["협업과 조정", "세밀한 기획"], "relationship": ["세심한 배려", "분명한 의사 표현"], "intro": "주변의 작은 변화를 잘 읽고 상황에 맞게 방법을 바꾸는 쪽에 가까워요. 강하게 밀어붙이기보다 연결점을 찾으며 길을 만드는 모습이 보여요.", "strength_text": "서로 다른 의견 사이에서 접점을 찾고, 작은 일을 오래 다듬는 힘이 있어요.", "caution_text": "상대의 마음을 먼저 살피다 보면 정작 내 바람을 뒤로 미룰 수 있어요. 양보할 수 없는 기준을 하나 정해 두세요.", "career_text": "협업을 조율하거나 사용자의 마음을 세밀하게 읽는 일에서 장점이 살아나요.", "relationship_text": "작은 배려를 잘 기억하고 돌려주는 편이에요. 서운함이 쌓이기 전에 짧고 구체적으로 이야기하는 연습이 도움이 돼요.", "branch_text": "사람 사이의 분위기를 부드럽게 맞추려는 면도 함께 있어요. 편안한 관계 안에서 내 의견도 분명히 드러내 보세요.", "subtitle": "관계의 결을 읽는 감각"}'),
('day', '丙辰', '{"code": "병진", "keywords": ["활동적", "추진력", "표현력", "승부욕"], "strengths": ["실행력", "리더십"], "weaknesses": ["성급함", "과열"], "career": ["주도적인 업무", "전문성 표현"], "relationship": ["직접적인 감정 표현", "강한 자기주장 주의"], "intro": "생각만 오래 붙잡기보다 직접 움직이며 답을 찾는 쪽에 가까워요. 마음에 불이 붙은 일에는 존재감이 선명해지고, 주변에도 의욕을 전하는 모습이 보여요.", "strength_text": "망설이는 상황에서 첫걸음을 떼고 사람들을 움직이게 하는 힘이 있어요. 잘하는 것을 드러낼 기회가 생기면 자신감도 함께 살아나요.", "caution_text": "속도가 붙을수록 결론을 서두르거나 한 번에 너무 많은 일을 맡기 쉬워요. 중요한 결정 앞에서는 한 박자 쉬며 끝까지 가져갈 여력을 확인해 보세요.", "career_text": "스스로 방향을 잡는 업무나 기획·발표처럼 전문성을 눈에 보이게 표현하는 일에서 강점을 살리기 좋아요.", "relationship_text": "좋아하는 마음을 비교적 직접적으로 전하는 편이에요. 내 확신이 상대에게는 압박으로 느껴질 수 있으니, 말을 건넨 뒤 상대의 속도도 기다려 주세요.", "branch_text": "지금 모습에 머물기보다 더 큰 가능성을 마음에 품는 면이 있어요. 여러 계획 중 이번에 실현할 한 가지를 골라 보세요.", "subtitle": "변화를 담아내는 가능성"}'),
('day', '丁巳', '{"code": "정사", "keywords": ["따뜻함", "집중력", "감수성"], "strengths": ["세심한 관찰", "몰입"], "weaknesses": ["걱정 쌓기", "감정 소모"], "career": ["전문 기술", "돌봄과 교육"], "relationship": ["깊은 교감", "감정의 경계"], "intro": "크게 드러내기보다 가까운 사람과 중요한 일에 오래 마음을 쓰는 쪽에 가까워요. 관심이 생긴 대상은 작은 차이까지 살피며 깊이를 더하는 모습이에요.", "strength_text": "작은 신호를 놓치지 않고 필요한 순간에 정교하게 힘을 쓰는 장점이 있어요.", "caution_text": "마음에 담아 둔 일이 많아지면 혼자 지칠 수 있어요. 신경 쓰이는 일을 적어 보고 내 몫과 상대의 몫을 나눠 보세요.", "career_text": "한 분야를 깊이 익히는 전문 업무나 누군가의 성장을 돕는 일에서 보람을 찾기 좋아요.", "relationship_text": "넓고 가벼운 만남보다 깊이 통하는 관계를 소중히 여겨요. 마음을 읽어 주기만 기다리기보다 필요한 도움을 말로 알려 주세요.", "branch_text": "겉으로 보이는 것보다 안쪽의 이유를 알고 싶어 하는 면도 있어요. 충분히 살펴본 뒤에는 작은 실행으로 생각을 확인해 보세요.", "subtitle": "깊이 살펴보는 집중력"}'),
('day', '戊午', '{"code": "무오", "keywords": ["안정감", "책임감", "신중함"], "strengths": ["지속력", "신뢰"], "weaknesses": ["변화 부담", "고집"], "career": ["장기 프로젝트", "운영 관리"], "relationship": ["든든한 지지", "유연한 대화"], "intro": "한번 맡은 일은 쉽게 흔들리지 않고 버텨 내는 쪽에 가까워요. 빠른 성과보다 오래 지킬 수 있는 기반을 중요하게 느낄 수 있어요.", "strength_text": "복잡한 상황에서도 중심을 잡고 일을 꾸준히 이어 가는 힘이 있어요.", "caution_text": "익숙한 방식을 지키려는 마음이 새로운 가능성을 좁힐 수 있어요. 큰 변화보다 작은 실험부터 시작해 보세요.", "career_text": "여러 사람의 일을 안정적으로 연결하는 운영이나 긴 호흡의 프로젝트에서 역량이 드러나요.", "relationship_text": "곁에 있어 주는 것 자체로 마음을 표현하는 편이에요. 상대는 말로 확인받고 싶을 수 있으니 고마움을 조금 더 자주 전해 보세요.", "branch_text": "마음이 움직이는 순간 표현과 행동도 함께 커지기 쉬워요. 몰입할 일과 쉬어 갈 시간을 나눠 두면 열정을 오래 이어 갈 수 있어요.", "subtitle": "마음을 행동으로 옮기는 열기"}'),
('day', '己未', '{"code": "기미", "keywords": ["포용력", "현실감각", "꼼꼼함"], "strengths": ["지원", "관리 능력"], "weaknesses": ["과한 배려", "걱정"], "career": ["자원 관리", "실무 지원"], "relationship": ["생활 속 배려", "요구 전달"], "intro": "눈앞의 필요를 살피고 현실적으로 도움이 되는 방법을 찾는 쪽에 가까워요. 작은 것을 챙기며 전체를 안정시키는 모습이 보여요.", "strength_text": "흩어진 일과 자원을 정리하고 다른 사람이 제 몫을 할 수 있게 돕는 힘이 있어요.", "caution_text": "모두를 챙기려다 내 계획이 계속 밀릴 수 있어요. 도움을 주기 전에 가능한 범위를 먼저 정해 보세요.", "career_text": "세부 운영을 다듬거나 사람과 자원을 효율적으로 연결하는 일에서 장점을 살리기 좋아요.", "relationship_text": "거창한 말보다 생활 속 배려를 중요하게 여겨요. 나도 돌봄을 받을 수 있도록 원하는 것을 숨기지 않아도 괜찮아요.", "branch_text": "내 일만큼 가까운 사람의 편안함을 살피는 면도 함께 있어요. 배려와 내 필요 사이의 균형을 잡아 보세요.", "subtitle": "주변을 살피는 다정함"}'),
('day', '庚申', '{"code": "경신", "keywords": ["결단력", "원칙", "도전"], "strengths": ["문제 해결", "실행"], "weaknesses": ["직설적 표현", "경직됨"], "career": ["문제 해결 업무", "체계 개선"], "relationship": ["명확한 약속", "부드러운 표현"], "intro": "문제가 보이면 핵심을 짚고 빠르게 정리하고 싶어 하는 쪽에 가까워요. 애매한 상태보다 기준이 분명한 상황에서 힘이 나기 쉬워요.", "strength_text": "어려운 결정을 피하지 않고 불필요한 과정을 줄이는 힘이 있어요.", "caution_text": "옳은 이야기도 너무 단단하게 전하면 상대가 마음을 닫을 수 있어요. 해결책을 말하기 전에 상대가 겪은 어려움을 먼저 들어 주세요.", "career_text": "엉킨 문제를 풀거나 비효율적인 체계를 개선하는 업무에서 역량이 살아나요.", "relationship_text": "말과 행동이 일치하는 관계를 편안하게 느껴요. 약속만큼 감정도 대화의 주제로 두면 관계가 더 부드러워져요.", "branch_text": "변화하는 상황에 맞춰 방법을 바꾸는 재치도 함께 보여요. 새로운 방법을 찾되 마무리 기준은 일정하게 두면 좋아요.", "subtitle": "상황에 맞춰 움직이는 재치"}'),
('day', '辛酉', '{"code": "신유", "keywords": ["정교함", "분석력", "미감"], "strengths": ["완성도", "집중력"], "weaknesses": ["완벽주의", "예민함"], "career": ["분석과 검수", "정밀한 표현"], "relationship": ["섬세한 취향", "기대 조율"], "intro": "작은 차이에서도 의미를 찾아내고 내 기준에 맞게 다듬는 쪽에 가까워요. 대충 넘어가기보다 완성도를 높일 때 만족감이 커질 수 있어요.", "strength_text": "세부의 오류를 찾고 결과물의 품질을 한 단계 올리는 힘이 있어요.", "caution_text": "완벽한 상태를 기다리면 시작이나 마무리가 늦어질 수 있어요. 이번 단계에 충분한 기준을 먼저 정해 보세요.", "career_text": "분석·검수나 정교한 감각을 표현하는 업무에서 집중력이 빛나기 좋아요.", "relationship_text": "세심하게 알아주는 말에 마음이 움직이는 편이에요. 상대도 같은 기준을 알 수 있도록 기대를 구체적으로 나눠 주세요.", "branch_text": "무엇을 하든 마지막 완성도를 확인하려는 면도 있어요. 잘된 부분부터 인정하면 스스로에게 지나치게 엄격해지는 것을 줄일 수 있어요.", "subtitle": "결과를 다듬는 감각"}'),
('day', '壬戌', '{"code": "임술", "keywords": ["유연함", "탐구심", "넓은 시야"], "strengths": ["상황 판단", "연결 능력"], "weaknesses": ["방향 분산", "마무리 지연"], "career": ["정보 연결", "전략 수립"], "relationship": ["열린 대화", "일관된 표현"], "intro": "한 가지 답에 묶이기보다 여러 가능성을 살피는 쪽에 가까워요. 사람과 정보 사이의 흐름을 읽으며 새로운 길을 찾아가는 모습이에요.", "strength_text": "서로 떨어져 있던 생각을 연결하고 큰 흐름 속에서 선택지를 찾는 힘이 있어요.", "caution_text": "가능성이 많을수록 방향이 자주 바뀔 수 있어요. 지금 끝낼 일 하나를 고르면 넓은 시야가 실행으로 이어져요.", "career_text": "정보를 엮어 전략을 만들거나 다양한 사람을 연결하는 일에서 장점이 살아나요.", "relationship_text": "생각을 자유롭게 나눌 수 있는 관계를 편안하게 느껴요. 중요한 마음은 상황이 바뀌어도 일관되게 보여 주는 것이 좋아요.", "branch_text": "마음속 약속과 기준을 쉽게 버리지 않는 면도 함께 있어요. 원칙을 지키면서도 방법에는 여지를 남겨 보세요.", "subtitle": "기준을 지키는 성실함"}'),
('day', '癸亥', '{"code": "계해", "keywords": ["직관", "관찰력", "신중함"], "strengths": ["공감", "깊은 사고"], "weaknesses": ["과도한 생각", "표현 주저"], "career": ["연구와 기록", "세밀한 상담"], "relationship": ["조용한 교감", "솔직한 요청"], "intro": "먼저 충분히 관찰하고 내 안에서 생각을 정리하는 쪽에 가까워요. 겉으로 드러난 말보다 미묘한 분위기를 세심하게 읽는 모습이에요.", "strength_text": "다른 사람이 지나친 단서를 모아 새로운 이해로 연결하는 힘이 있어요.", "caution_text": "생각이 많아질수록 아직 일어나지 않은 일까지 걱정하기 쉬워요. 확인된 사실과 추측을 나눠 적어 보세요.", "career_text": "깊이 탐구하고 기록하거나 상대의 이야기를 세심하게 듣는 일에서 역량을 살리기 좋아요.", "relationship_text": "조용히 통하는 관계를 소중히 여기지만 내 마음이 저절로 전달되지는 않아요. 작은 요청부터 솔직하게 표현해 보세요.", "branch_text": "당장 드러난 결과보다 사람과 상황을 넓게 이해하려는 면도 있어요. 충분히 생각한 뒤에는 내 선택을 구체적인 약속으로 만들어 보세요.", "subtitle": "넓게 이해하는 여유"}'),
('balance', '木', '{"text": "생각을 키울 작은 배움이나 새로운 시도를 일상에 넣어 보세요. 단번에 바꾸기보다 매주 한 가지씩 확장하는 방식이 잘 맞아요."}'),
('balance', '火', '{"text": "생각만 정리하기보다 짧은 발표나 가벼운 대화로 밖에 표현해 보세요. 따뜻한 교류가 행동을 시작하는 계기가 될 수 있어요."}'),
('balance', '土', '{"text": "일정과 생활 리듬을 단순하게 정리해 보세요. 반복할 수 있는 작은 습관이 많아진 생각을 현실에 붙잡아 줘요."}'),
('balance', '金', '{"text": "지금 필요한 일과 내려놓을 일을 구분해 보세요. 끝낼 기준을 먼저 정하면 에너지를 덜 흩뜨리면서 완성도를 높일 수 있어요."}'),
('balance', '水', '{"text": "바로 반응하기보다 잠깐 멈춰 생각을 정리하는 시간을 가져 보세요. 충분히 듣고 적어 보는 습관이 빠른 흐름에 여유를 만들어 줘요."}'),
('career', '食神格', '{"text": "익힌 것을 꾸준히 결과물로 남길 때 실력이 더 잘 드러나요."}'),
('career', '傷官格', '{"text": "기존 방식을 개선할 아이디어가 있다면 작은 시제품으로 보여 주세요."}'),
('career', '偏財格', '{"text": "새 기회를 넓히되 시간과 자원의 한도를 먼저 정해 두면 좋아요."}'),
('career', '正財格', '{"text": "눈에 띄는 성과만큼 일정과 세부 관리를 꾸준히 챙기는 것이 힘이 돼요."}'),
('career', '偏官格', '{"text": "도전적인 역할에서는 혼자 버티기보다 역할과 책임을 분명히 나눠 보세요."}'),
('career', '正官格', '{"text": "명확한 기준과 약속이 있는 환경에서 신뢰를 쌓아 가기 좋아요."}'),
